class Checkout:
    """Accumulates basket contents and computes the final payable amount."""

    def __init__(self, rate=0.0):
        self._quantities = {}
        self._prices = {}
        self._discount_pct = 0.0
        self._stock_limit = 99
        self.set_tax(rate)

    def add(self, name, quantity, price):
        allowed = self._room_for(name, int(quantity))
        if allowed > 0:
            self._prices[name] = float(price)
            self._quantities[name] = self._quantities.get(name, 0) + allowed

    def remove(self, name, quantity):
        if name in self._quantities:
            left = self._quantities[name] - int(quantity)
            if left > 0:
                self._quantities[name] = left
            else:
                del self._quantities[name]
                del self._prices[name]

    def set_discount(self, percentage):
        percentage = float(percentage)
        if 0.0 <= percentage <= 100.0:
            self._discount_pct = percentage

    def set_tax(self, rate):
        self._tax_rate = max(0.0, float(rate))

    def total(self):
        payable = self._discounted(self._subtotal())
        return round(payable + self._tax_on(payable), 2)

    def _room_for(self, name, quantity):
        return min(quantity, self._stock_limit - self._quantities.get(name, 0))

    def _subtotal(self):
        return sum(count * self._prices[name]
                   for name, count in self._quantities.items())

    def _discounted(self, amount):
        return amount * (1.0 - self._discount_pct / 100.0)

    def _tax_on(self, amount):
        return amount * self._tax_rate


def cart(actions):
    checkout = Checkout()
    for action in actions:
        verb = action[0]
        if verb == "add":
            checkout.add(action[1], action[2], action[3])
        elif verb == "remove":
            checkout.remove(action[1], action[2])
        elif verb == "discount":
            checkout.set_discount(action[1])
        elif verb == "tax":
            checkout.set_tax(action[1])
        else:
            raise ValueError("unknown action: {0!r}".format(verb))
    return float(checkout.total())


def main():
    basket = [("add", "shirt", 2, 20.0), ("discount", 10)]
    print("%.2f" % cart(basket))
    mixed = [("add", "mug", 4, 7.5), ("remove", "mug", 1),
             ("discount", 25), ("tax", 0.08)]
    print("%.2f" % cart(mixed))


if __name__ == "__main__":
    main()

