PIGMENT_ORDER = ("cyan", "magenta", "yellow", "black")


class PaintMixer:
    """Dispenses custom shades from four pigment reservoirs plus a white base."""

    BASE_WHITE_PER_BATCH = 10

    def __init__(self, start_volume=100, white_volume=500):
        self._reservoirs = {name: start_volume for name in PIGMENT_ORDER}
        self._white = white_volume
        self._log = []

    def _parse(self, request):
        if not request or request[0] != "mix":
            raise ValueError("request must begin with 'mix': %r" % (request,))
        amounts = request[1:]
        if len(amounts) != len(PIGMENT_ORDER):
            raise ValueError("expected %d drop counts, got %d" % (len(PIGMENT_ORDER), len(amounts)))
        drops = {}
        for name, value in zip(PIGMENT_ORDER, amounts):
            if not isinstance(value, int) or isinstance(value, bool) or value < 0:
                raise ValueError("drops of %s must be a non-negative integer: %r" % (name, value))
            drops[name] = value
        return drops

    def _sufficient(self, drops):
        if self._white < self.BASE_WHITE_PER_BATCH:
            return False
        return all(self._reservoirs[name] >= volume for name, volume in drops.items())

    def _deduct(self, drops):
        for name, volume in drops.items():
            self._reservoirs[name] -= volume
        self._white -= self.BASE_WHITE_PER_BATCH

    def dispense(self, request):
        drops = self._parse(request)
        if not self._sufficient(drops):
            self._log.append((drops, False))
            return False
        self._deduct(drops)
        self._log.append((drops, True))
        return True

    def remaining(self):
        return tuple(self._reservoirs[name] for name in PIGMENT_ORDER)

    def report(self):
        lines = []
        for index, (drops, served) in enumerate(self._log, start=1):
            recipe = " ".join("%s=%d" % (name, drops[name]) for name in PIGMENT_ORDER)
            lines.append("batch %d: %s -> %s" % (index, recipe, "mixed" if served else "refused"))
        lines.append("remaining: %s" % (", ".join(
            "%s=%d" % (name, volume) for name, volume in zip(PIGMENT_ORDER, self.remaining()))))
        lines.append("white base left: %d" % self._white)
        return "\n".join(lines)


def mixer(requests):
    machine = PaintMixer()
    for request in requests:
        machine.dispense(request)
    return machine.remaining()


def main():
    batch = [("mix", 10, 20, 0, 5), ("mix", 5, 5, 5, 5), ("mix", 200, 0, 0, 0)]
    machine = PaintMixer()
    for request in batch:
        machine.dispense(request)
    print(machine.report())
    print("single order:", mixer([("mix", 10, 20, 0, 5)]))


if __name__ == "__main__":
    main()

