class _LedgerNode:
    """A ledger node: validates transfers, pools them, seals them into blocks."""

    def __init__(self):
        self._height = 0
        self._ledger = {}
        self._pending = []
        self._fees = 0

    def _parse(self, tx):
        if not isinstance(tx, (tuple, list)) or not tx:
            raise ValueError("transaction must be a non-empty tuple")
        kind = tx[0]
        if kind == "send":
            if len(tx) != 5:
                raise ValueError("send needs sender, receiver, amount, fee")
            if tx[3] < 0 or tx[4] < 0:
                raise ValueError("amount and fee must be non-negative")
            return ("send", tx[1], tx[2], tx[3], tx[4])
        if kind == "deposit":
            if len(tx) != 3 or tx[2] < 0:
                raise ValueError("deposit needs an account and a non-negative amount")
            return ("deposit", tx[1], tx[2])
        if kind == "mine":
            return ("mine",)
        raise ValueError("unknown transaction kind: %r" % (kind,))

    def _credit(self, account, amount):
        self._ledger[account] = self._ledger.get(account, 0) + amount

    def _has_funds(self, sender, amount, fee):
        return self._ledger.get(sender, 0) >= amount + fee

    def _spend(self, sender, receiver, amount, fee):
        if not self._has_funds(sender, amount, fee):
            return False
        self._ledger[sender] -= amount + fee
        self._credit(receiver, amount)
        self._pending.append((sender, receiver, amount, fee))
        return True

    def _seal_block(self):
        block = (self._height + 1, tuple(self._pending))
        for sender, receiver, amount, fee in self._pending:
            self._fees += fee
        self._pending = []
        self._height += 1
        return block

    def submit(self, tx):
        kind, *rest = self._parse(tx)
        if kind == "send":
            return self._spend(*rest)
        if kind == "deposit":
            self._credit(*rest)
            return True
        return self._seal_block()

    def balances(self):
        return sorted(self._ledger.items())

    def summary(self):
        return "height=%d fees=%d pending=%d" % (self._height, self._fees, len(self._pending))


def validator(blocks):
    node = _LedgerNode()
    for tx in blocks:
        node.submit(tx)
    return node.balances()


def main():
    node = _LedgerNode()
    for tx in [("deposit", "alice", 50), ("send", "alice", "bob", 10, 1),
               ("send", "bob", "carol", 99, 1), ("mine",)]:
        node.submit(tx)
    for account, amount in node.balances():
        print("%-6s %d" % (account, amount))
    print(node.summary())
    print(validator([("deposit", "alice", 50), ("send", "alice", "bob", 10, 1), ("mine",)]))


if __name__ == "__main__":
    main()

