class _SkiLift:
    """Drives a chairlift: chairs rotate upward, passengers board at the bottom."""

    _CHAIRS = 4
    _SEATS = 4
    _SLOW_WIND = 25
    _STOP_WIND = 50

    def __init__(self):
        self._chairs = [0] * self._CHAIRS
        self._queue = 0
        self._wind = 0
        self._mode = "normal"
        self._delivered = 0
        self._tick = 0

    def _parse(self, conditions):
        parsed = []
        for entry in conditions:
            if len(entry) != 2:
                raise ValueError("each condition needs an action and a value: %r" % (entry,))
            action, value = entry
            action = str(action).lower()
            if action not in ("wind", "load"):
                raise ValueError("unknown action: %r" % (action,))
            value = int(value)
            if value < 0:
                raise ValueError("%s value cannot be negative: %d" % (action, value))
            parsed.append((action, value))
        return parsed

    def _wind_safe(self):
        return self._wind < self._STOP_WIND

    def _throttle(self):
        self._mode = "slow" if self._wind >= self._SLOW_WIND else "normal"

    def _board(self):
        free = self._SEATS - self._chairs[0]
        boarding = min(free, self._queue)
        self._chairs[0] += boarding
        self._queue -= boarding

    def _unload(self):
        self._delivered += self._chairs[-1]
        self._chairs[-1] = 0

    def _advance(self):
        self._unload()
        self._chairs = [0] + self._chairs[:-1]

    def _step(self):
        self._tick += 1
        if not self._wind_safe():
            return
        if self._mode == "slow" and self._tick % 2 == 0:
            return
        self._board()
        self._advance()

    def _summary(self):
        stranded = self._queue + sum(self._chairs)
        return "wind %d km/h, motor %s, %d dropped at the top, %d still waiting" % (
            self._wind, self._mode, self._delivered, stranded)

    def report(self):
        return self._summary()

    def run(self, conditions):
        for action, value in self._parse(conditions):
            if action == "wind":
                self._wind = value
                self._throttle()
            else:
                self._queue += value
            self._step()
        while self._wind_safe() and (self._queue or any(self._chairs)):
            self._step()
        return self._delivered


def skilift(conditions):
    return _SkiLift().run(conditions)


if __name__ == "__main__":
    calm_day = [("load", 4), ("wind", 10), ("load", 2)]
    print("delivered:", skilift(calm_day))
    stormy_day = [("load", 3), ("wind", 60), ("load", 1)]
    lift = _SkiLift()
    lift.run(stormy_day)
    print(lift.report())

