    def log_plate(self, plate, axles):
        self.violator_plates.append((plate, self.axle_toll(axles)))

    def take_cash(self, axles, amount):
        self.check_axles(axles)
        if amount < 0:
            raise ValueError("cash payment cannot be negative")
        self.cash_total += amount
        self.open_barrier()
        self.close_barrier()

    def scan_pass(self, axles, tag):
        self.passes.append((tag, self.axle_toll(axles)))
        self.open_barrier()
        self.close_barrier()

    def record_runaway(self, axles, plate):
        self.close_barrier()
        self.log_plate(plate, axles)

    @property
    def revenue(self):
        billed = sum(entry[1] for entry in self.passes)
        return round(self.cash_total + billed, 2)

    @property
    def violator_count(self):
        return len(self.violator_plates)

    def summary(self):
        lines = ["revenue={0:.2f} violators={1}".format(self.revenue,
                                                        self.violator_count)]
        for plate, owed in self.violator_plates:
            lines.append("  unpaid {0} owes {1:.2f}".format(plate, owed))
        return "\n".join(lines)


def tollbooth(vehicles):
    lane = TollLane()
    for kind, axles, extra in vehicles:
        if kind == "cash":
            lane.take_cash(axles, extra)
        elif kind == "pass":
            lane.scan_pass(axles, extra)
        elif kind == "run":
            lane.record_runaway(axles, extra)
        else:
            raise ValueError("unknown event type: {0!r}".format(kind))
    return lane.revenue, lane.violator_count


def main():
    lane = TollLane()
    lane.take_cash(2, 5.00)
    lane.record_runaway(4, "ABC-1234")
    lane.scan_pass(3, "TAG-77")
    print(lane.summary())


if __name__ == "__main__":
    main()

