class SailboatAutopilot:
    """Tracks heading, wind angle and rudder position for a sailboat."""

    NORMAL_LIMIT = 35
    TACKING_LIMIT = 45
    TACKING_WINDOW = 30

    def __init__(self, heading=0, wind_angle=0):
        self.heading = self._clamp(heading)
        self.wind_angle = self._clamp(wind_angle)
        self.rudder = 0
        self.tacking = False
        self._cache = {}
        self._log = []

    def _clamp(self, degrees):
        return int(round(degrees)) % 360

    def _shortest_turn(self, start, end):
        key = (start, end)
        if key not in self._cache:
            diff = (end - start + 180) % 360 - 180
            self._cache[key] = diff
        return self._cache[key]

    def _rudder_for(self, turn, tacking):
        gain = 0.75 if tacking else 0.5
        limit = self.TACKING_LIMIT if tacking else self.NORMAL_LIMIT
        angle = turn * gain
        if angle > limit:
            angle = limit
        elif angle < -limit:
            angle = -limit
        return int(round(angle))

    def _is_tacking(self, target, wind):
        return abs(self._shortest_turn(target, wind)) <= self.TACKING_WINDOW

    def _validate(self, instruction):
        try:
            target, wind = instruction
        except (TypeError, ValueError):
            raise ValueError("instruction must be a (heading, wind_angle) pair")
        if not isinstance(target, (int, float)) or not isinstance(wind, (int, float)):
            raise ValueError("heading and wind angle must be numeric")
        return self._clamp(target), self._clamp(wind)

    def step(self, instruction):
        target, wind = self._validate(instruction)
        turn = self._shortest_turn(self.heading, target)
        self.tacking = self._is_tacking(target, wind)
        self.rudder = self._rudder_for(turn, self.tacking)
        self.heading = target
        self.wind_angle = wind
        self._log.append((target, wind, turn, self.rudder, self.tacking))
        return self.rudder

    def run(self, instructions):
        return [self.step(item) for item in instructions]

    def report(self):
        lines = ["heading  wind  turn  rudder  mode"]
        for target, wind, turn, rudder, tacking in self._log:
            mode = "tacking" if tacking else "cruising"
            lines.append("%7d %5d %5d %7d  %s" % (target, wind, turn, rudder, mode))
        return "\n".join(lines)


def navigate(instructions):
    pilot = SailboatAutopilot()
    return pilot.run(instructions)


def main():
    course = [(30, 45), (120, 200), (350, 10), (180, 175), (90, 300)]
    pilot = SailboatAutopilot()
    rudders = pilot.run(course)
    print(pilot.report())
    print("rudder angles:", rudders)
    print("final heading:", pilot.heading, "wind:", pilot.wind_angle)


if __name__ == "__main__":
    main()

