class AuctionHouse:
    """Runs an online auction: tracks leading bids, history and reserve prices."""

    def __init__(self, reserve_prices=None):
        self._reserves = {}
        self._highest_bid = {}
        self._leading = {}
        self._bid_log = []
        self._load(reserve_prices or {})

    def _load(self, reserve_prices):
        for item, price in reserve_prices.items():
            self._reserves[str(item)] = float(price)

    def _reserve_for(self, item):
        return self._reserves.get(item, 0.0)

    @staticmethod
    def _unpack(offer):
        if isinstance(offer, dict):
            return offer["bidder"], offer["item"], float(offer["amount"])
        bidder, item, amount = offer
        return bidder, item, float(amount)

    def _accepts(self, item, amount):
        return amount > self._reserve_for(item) and amount > self._highest_bid.get(item, 0.0)

    def _log(self, bidder, item, amount, accepted):
        self._bid_log.append({"bidder": bidder, "item": item,
                              "amount": amount, "accepted": accepted})

    def _record(self, bidder, item, amount):
        self._highest_bid[item] = amount
        self._leading[item] = bidder

    def evaluate(self, bids):
        for offer in bids:
            bidder, item, amount = self._unpack(offer)
            accepted = self._accepts(item, amount)
            if accepted:
                self._record(bidder, item, amount)
            self._log(bidder, item, amount, accepted)
        return [[self._leading[item], self._highest_bid[item]] for item in sorted(self._leading)]

    def bid_history(self):
        return list(self._bid_log)

    def summary(self):
        lines = []
        for item in sorted(self._reserves):
            reserve = self._reserve_for(item)
