class TrainReservation:
    """Seat reservation ledger for a single passenger train."""

    _ACTIONS = ("book", "cancel")

    def __init__(self, total_seats):
        self._unassigned = self._checked_seats(total_seats)
        self._bookings = {}
        self._waiting = []
        self._cancellations = 0

    @classmethod
    def _checked_seats(cls, seats):
        count = int(seats)
        if count < 0:
            raise ValueError("seat count may not be negative")
        return count

    def _parse(self, request):
        parts = request.split() if isinstance(request, str) else list(request)
        if len(parts) != 3:
            raise ValueError("a request needs an action, a name and a seat count")
        action = str(parts[0]).strip().lower()
        if action not in self._ACTIONS:
            raise ValueError("unknown action: {!r}".format(parts[0]))
        return action, str(parts[1]), self._checked_seats(parts[2])

    def _book(self, name, seats):
        if seats <= self._unassigned:
            self._unassigned -= seats
            self._bookings[name] = self._bookings.get(name, 0) + seats
        else:
            self._waiting.append((name, seats))

    def _cancel(self, name, seats):
        self._unassigned += seats
        self._bookings.pop(name, None)
        self._cancellations += 1

    def process(self, requests):
        for request in requests:
            action, name, seats = self._parse(request)
            if action == "book":
                self._book(name, seats)
            else:
                self._cancel(name, seats)
        return self._unassigned, self._cancellations

    def report(self):
        lines = ["unassigned seats: {}".format(self._unassigned),
                 "cancellations: {}".format(self._cancellations)]
        for name in sorted(self._bookings):
            lines.append("booked  {}: {}".format(name, self._bookings[name]))
        for name, seats in self._waiting:
            lines.append("waiting {}: {}".format(name, seats))
        return "\n".join(lines)


def main():
    train = TrainReservation(10)
    remaining, cancelled = train.process([
        "book Alice 5",
        "book Bob 3",
        "book Carol 4",
        ("cancel", "Alice", 2),
    ])
    print("{} seats free, {} cancellation(s)".format(remaining, cancelled))
    print(train.report())


if __name__ == "__main__":
    main()

