class BoardingFacility:
    """Manages cage reservations at an animal boarding facility."""

    _RATES = {"small": 20, "large": 35}

    def __init__(self, small_cages=5, large_cages=3):
        self.small_cages = small_cages
        self.large_cages = large_cages
        self.boarded = {}
        self.total_days = 0
        self.total_fees = 0
        self._rejected = []

    def _rate(self, size):
        return self._RATES[size]

    def _parse(self, record):
        activity, name, size, days = record
        activity = str(activity).strip().lower()
        size = str(size).strip().lower()
        if size not in self._RATES:
            raise ValueError("unknown size category: {!r}".format(size))
        return activity, str(name), size, int(days)

    def _available(self, size):
        return self.small_cages if size == "small" else self.large_cages

    def _adjust_cages(self, size, delta):
        if size == "small":
            self.small_cages += delta
        else:
            self.large_cages += delta

    def _arrive(self, name, size):
        if name in self.boarded or self._available(size) <= 0:
            self._rejected.append((name, size))
            return
        self._adjust_cages(size, -1)
        self.boarded[name] = size

    def _depart(self, name, days):
        size = self.boarded.pop(name, None)
        if size is None:
            self._rejected.append((name, None))
            return
        self._adjust_cages(size, 1)
        self.total_days += days
        self.total_fees += days * self._rate(size)

    def board(self, records):
        for record in records:
            activity, name, size, days = self._parse(record)
            if activity == "arrival":
                self._arrive(name, size)
            elif activity == "departure":
                self._depart(name, days)
            else:
                raise ValueError("unknown activity: {!r}".format(activity))
        return self.total_days, self.total_fees

    def report(self):
        lines = ["Total days boarded: {}".format(self.total_days),
                 "Total fees billed: {}".format(self.total_fees),
                 "Cages free: {} small, {} large".format(self.small_cages, self.large_cages)]
        if self.boarded:
            still = ", ".join("{} ({})".format(n, s) for n, s in sorted(self.boarded.items()))
            lines.append("Still boarded: " + still)
        for name, size in self._rejected:
            if size is None:
                lines.append("Rejected departure: {} was not boarded".format(name))
            else:
                lines.append("Rejected arrival: no {} cage for {}".format(size, name))
        return "\n".join(lines)


def main():
    facility = BoardingFacility(small_cages=1, large_cages=1)
    daily_log = [
        ("arrival", "Milo", "small", 0),
        ("arrival", "Bella", "large", 0),
        ("arrival", "Rex", "small", 0),
        ("departure", "Milo", "small", 2),
        ("departure", "Bella", "large", 4),
    ]
    days, fees = facility.board(daily_log)
    print("Returned: {} total days, {} billed fees".format(days, fees))
    print(facility.report())


if __name__ == "__main__":
    main()

