from collections import Counter, deque


class DefectMonitor:
    """Tracks defect statistics for a microchip production line."""

    CRITICAL_COUNT = 10
    _CLEAN_LABELS = frozenset({"", "none", "no defect", "ok", "pass", "clean"})

    def __init__(self):
        self.total_inspected = 0
        self.defect_counts = Counter()
        self.rework_queue = deque()
        self.passed_inspection = []
        self._halted_on = None

    def _normalize(self, category):
        if category is None:
            return ""
        return str(category).strip().lower()

    def _is_clean(self, category):
        return self._normalize(category) in self._CLEAN_LABELS

    def _record_defect(self, item_id, category):
        label = self._normalize(category)
        self.defect_counts[label] += 1
        self.rework_queue.append(item_id)
        return self.defect_counts[label]

    def inspect(self, batches):
        for item_id, category in batches:
            self.total_inspected += 1
            if self._is_clean(category):
                self.passed_inspection.append(item_id)
                continue
            if self._record_defect(item_id, category) >= self.CRITICAL_COUNT:
                self._halted_on = self._normalize(category)
                break
        return len(self.passed_inspection), len(self.rework_queue)

    def release_next(self):
        """Pop the next item awaiting rework, or None if the queue is empty."""
        if not self.rework_queue:
            return None
        return self.rework_queue.popleft()

    def _yield_rate(self):
        if self.total_inspected == 0:
            return 0.0
        return len(self.passed_inspection) / self.total_inspected

    def _ranked_defects(self):
        return sorted(self.defect_counts.items(), key=lambda kv: (-kv[1], kv[0]))

    def report(self):
        lines = ["Inspected: %d" % self.total_inspected,
                 "Passed: %d" % len(self.passed_inspection),
                 "Awaiting rework: %d" % len(self.rework_queue),
                 "Yield: %.1f%%" % (100.0 * self._yield_rate())]
        for label, count in self._ranked_defects():
            lines.append("  %-18s %d" % (label, count))
        if self._halted_on is not None:
            lines.append("HALTED: '%s' reached %d occurrences"
                         % (self._halted_on, self.CRITICAL_COUNT))
        return "\n".join(lines)


def main():
    monitor = DefectMonitor()
    batch = [("MC-001", "none"), ("MC-002", "solder bridge"), ("MC-003", "OK"),
             ("MC-004", "cracked die"), ("MC-005", ""), ("MC-006", "solder bridge")]
    passed, pending = monitor.inspect(batch)
    print("first pass -> passed=%d rework=%d" % (passed, pending))

    stress = [("MC-1%02d" % i, "solder bridge") for i in range(20)]
    passed, pending = monitor.inspect(stress)
    print("second pass -> passed=%d rework=%d" % (passed, pending))

    print("reworking:", monitor.release_next(), monitor.release_next())
    print(monitor.report())


if __name__ == "__main__":
    main()

