import sys


class SensorTracker:
    """Tracks sensor readings and flags values that drift from the moving average."""

    WINDOW = 5
    TOLERANCE = 0.20

    def __init__(self):
        self._windows = {}
        self._flagged = []

    def _normalize(self, reading):
        try:
            name, timestamp, value = reading
        except (TypeError, ValueError):
            raise ValueError("each reading must be a (name, timestamp, value) tuple")
        if not isinstance(name, str) or not name.strip():
            raise ValueError("sensor name must be a non-empty string")
        if not isinstance(timestamp, int) or isinstance(timestamp, bool):
            raise ValueError("timestamp must be an integer")
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError("value must be numeric")
        return name.strip(), timestamp, float(value)

    def _window_for(self, name):
        return self._windows.setdefault(name, [])

    def _moving_average(self, window):
        if len(window) < self.WINDOW:
            return None
        return sum(pair[1] for pair in window) / len(window)

    def _is_anomaly(self, average, value):
        if average == 0:
            return value != 0
        return abs(value - average) / abs(average) > self.TOLERANCE

    def _record(self, name, timestamp, value):
        window = self._window_for(name)
        window.append((timestamp, value))
        if len(window) > self.WINDOW:
            del window[0]

    def _describe(self, name, value):
        if value == int(value):
            value = int(value)
        return "{} anomaly at {}".format(name, value)

    def process(self, readings):
        for reading in sorted(readings, key=lambda item: item[1]):
            name, timestamp, value = self._normalize(reading)
            average = self._moving_average(self._window_for(name))
            if average is not None and self._is_anomaly(average, value):
                self._flagged.append(self._describe(name, value))
            self._record(name, timestamp, value)
        return list(self._flagged)

    def report(self):
        lines = []
        for name in sorted(self._windows):
            window = self._windows[name]
            average = self._moving_average(window)
            shown = "n/a" if average is None else "{:.2f}".format(average)
            lines.append("{}: last_t={} values={} avg={}".format(
                name, window[-1][0], [pair[1] for pair in window], shown))
        return "\n".join(lines)


def track(readings):
    return SensorTracker().process(readings)


def parse_line(line):
    parts = line.split()
    if len(parts) != 3:
        raise ValueError("expected 'name timestamp value', got {!r}".format(line))
    return parts[0], int(parts[1]), float(parts[2])


def main():
    readings = [parse_line(line) for line in sys.stdin if line.strip()]
    tracker = SensorTracker()
    for anomaly in tracker.process(readings):
        print(anomaly)
    print(tracker.report())


if __name__ == "__main__":
    main()

