from collections import deque
import sys


class FoodTruck:
    """Single-window food truck: one order cooking, the rest waiting in line."""

    def __init__(self):
        self._queue = deque()
        self._active = None
        self._served = []

    def process(self, actions):
        for action in actions:
            if isinstance(action, tuple):
                name, minutes = action
                self.place_order(name, minutes)
            else:
                self.advance(action)

    def place_order(self, name, minutes):
        self._check_order(name, minutes)
        self._queue.append((name, minutes))
        if self._active is None:
            self._start_next()

    def advance(self, minutes):
        self._check_elapsed(minutes)
        left = minutes
        while left > 0 and self._active is not None:
            name, remaining = self._active
            if remaining > left:
                self._active = (name, remaining - left)
                left = 0
            else:
                left -= remaining
                self._served.append(name)
                self._active = None
                self._start_next()

    def _start_next(self):
        if self._queue:
            self._active = self._queue.popleft()

    def _check_order(self, name, minutes):
        if not isinstance(name, str) or not name.strip():
            raise ValueError("customer name must be a non-empty string: %r" % (name,))
        if not isinstance(minutes, int) or isinstance(minutes, bool) or minutes <= 0:
            raise ValueError("preparation time must be a positive integer: %r" % (minutes,))

    def _check_elapsed(self, minutes):
        if not isinstance(minutes, int) or isinstance(minutes, bool) or minutes < 0:
            raise ValueError("elapsed time must be a non-negative integer: %r" % (minutes,))

    def summary(self):
        lines = ["served: " + (", ".join(self._served) or "nobody")]
        if self._active is not None:
            lines.append("cooking: %s (%d min left)" % self._active)
        if self._queue:
            lines.append("waiting: " + ", ".join(order[0] for order in self._queue))
        return "\n".join(lines)

    def completed(self):
        return list(self._served)


def serve(actions):
    truck = FoodTruck()
    truck.process(actions)
    return truck.completed()


def parse_actions(tokens):
    actions = []
    for token in tokens:
        if ":" in token:
            name, minutes = token.split(":", 1)
            actions.append((name, int(minutes)))
        else:
            actions.append(int(token))
    return actions


def main(argv):
    if not argv:
        raise SystemExit("usage: truck.py NAME:MINUTES|ELAPSED ...")
    truck = FoodTruck()
    truck.process(parse_actions(argv))
    print(truck.summary())


if __name__ == "__main__":
    main(sys.argv[1:])

