class Drivetrain:
    """A three-by-seven drivetrain that tracks gear positions and wear."""

    LIMITS = {"front": 3, "rear": 7}
    COSTS = {"front": 2, "rear": 1}
    DIRECTIONS = {"up": 1, "down": -1}

    def __init__(self):
        self.position = {"front": 1, "rear": 1}
        self.wear = 0

    def parse(self, command):
        pieces = command.split()
        if len(pieces) != 2:
            raise ValueError("malformed command: %r" % command)
        part, direction = pieces
        if part not in self.LIMITS or direction not in self.DIRECTIONS:
            raise ValueError("unknown command: %r" % command)
        return part, direction

    def shift(self, part, direction):
        target = self.position[part] + self.DIRECTIONS[direction]
        if 1 <= target <= self.LIMITS[part]:
            self.position[part] = target
            self.wear += self.COSTS[part]

    def ratio(self):
        return round(self.position["front"] / self.position["rear"], 2)

    def execute(self, command):
        part, direction = self.parse(command)
        self.shift(part, direction)
        return self.ratio()

    def describe(self):
        return "front %d/%d, rear %d/%d" % (
            self.position["front"], self.LIMITS["front"],
            self.position["rear"], self.LIMITS["rear"],
        )

    def summary(self):
        return "%s | wear %d | ratio %.2f" % (self.describe(), self.wear, self.ratio())


def ride(commands):
    bike = Drivetrain()
    return [bike.execute(command) for command in commands]


def report(commands):
    bike = Drivetrain()
    lines = ["%-11s -> %.2f" % (command, bike.execute(command)) for command in commands]
    lines.append(bike.summary())
    return lines


def main():
