class SentenceCapitalizer:
    def __init__(self, _text_input=""):
        self._input_text = _text_input
        self._output_text = ""
        self._delimiters = ['.', '!', '?']
        self._current_index = 0
        self._capitalize_next = True
        self._processed_chars = []
        self._sentence_count = 0

    def _is_sentence_delimiter(self, _char):
        return _char in self._delimiters

    def _process_character(self, _char):
        if self._capitalize_next and _char.isalpha():
            self._processed_chars.append(_char.upper())
            self._capitalize_next = False
        else:
            self._processed_chars.append(_char)

        if self._is_sentence_delimiter(_char):
            self._capitalize_next = True
            self._sentence_count += 1

    def _process_all_characters(self):
        for _char in self._input_text:
            self._process_character(_char)

    def _build_output_string(self):
        self._output_text = "".join(self._processed_chars)

    def _reset_state(self):
        self._output_text = ""
        self._current_index = 0
        self._capitalize_next = True
        self._processed_chars = []
        self._sentence_count = 0

    def capitalize_sentences(self, text):
        self._reset_state()
        self._input_text = text
        self._process_all_characters()
