    def __init__(self, _text_input=""):
        self.input_text = _text_input
        self.output_text = ""
        self.delimiters = ['.', '!', '?']
        self.current_index = 0
        self.capitalize_next = True
        self.processed_chars = []
        self.sentence_count = 0

