        return _char in self.delimiters

    def process_character(self, _char):
        if self.capitalize_next and _char.isalpha():
            self.processed_chars.append(_char.upper())
            self.capitalize_next = False
        else:
            self.processed_chars.append(_char)

        if self.is_sentence_delimiter(_char):
            self.capitalize_next = True
            self.sentence_count += 1

    def process_all_characters(self):
