        if not self._is_calculated:
            self._hours = self._total_seconds // self._conversion_factor_hour
            _remaining_seconds = self._total_seconds % self._conversion_factor_hour
            self._minutes = _remaining_seconds // self._conversion_factor_minute
            self._seconds = _remaining_seconds % self._conversion_factor_minute
            self._is_calculated = True

    def _reset_calculation(self):
        self._is_calculated = False

    def _format_time(self):
        self._calculate_hms()
        return self._result_format.format(self._hours, self._minutes, self._seconds)

    def seconds_to_hms(self, seconds):
        if not isinstance(seconds, int) or seconds < 0:
            raise ValueError("Input must be a non-negative integer.")
        self._total_seconds = seconds
        self._reset_calculation()
        return self._format_time()

