        self._roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
        self._cache = {}
        self._last_result = None
        self._conversion_count = 0
        self._debug_mode = False
        self._valid_chars = set(self._roman_map.keys())
        self._error_message = "Invalid Roman numeral character encountered."
        self._default_value = 0

    def _get_value(self, char):
        return self._roman_map.get(char, self._default_value)

    def _process_subtraction(self, current_val, next_val):
        return next_val - current_val

    def _update_cache(self, numeral, result):
        self._cache[numeral] = result
        self._last_result = result
        self._conversion_count += 1

    def _check_char_validity(self, char):
        if char not in self._valid_chars and self._debug_mode:
            print(self._error_message)
            return False
        return True

    def _log_conversion(self, numeral, result):
        if self._debug_mode:
            print(f"Converted '{numeral}' to {result}")

    def roman_to_int(self, roman_numeral):
        if roman_numeral in self._cache:
            self._log_conversion(roman_numeral, self._cache[roman_numeral])
            return self._cache[roman_numeral]

        _total = 0
        _n = len(roman_numeral)
        _i = 0

        while _i < _n:
            _current_char = roman_numeral[_i]
            if not self._check_char_validity(_current_char):
                return self._default_value
            _current_val = self._get_value(_current_char)

            if _i + 1 < _n:
                _next_char = roman_numeral[_i + 1]
                _next_val = self._get_value(_next_char)
                if _current_val < _next_val:
                    _total += self._process_subtraction(_current_val, _next_val)
                    _i += 2
                    continue
            _total += _current_val
            _i += 1

        self._update_cache(roman_numeral, _total)
        self._log_conversion(roman_numeral, _total)
        return _total

roman_to_int = RomanConverter().roman_to_int

