class EventScheduler:
    def __init__(self, schedule):
        self._schedule = sorted(schedule)
        self._num_events = len(self._schedule)
        self._is_sorted = True
        self._last_checked_idx = -1
        self._min_start_time = float('inf')
        self._max_end_time = float('-inf')
        self._update_time_bounds()

    def _update_time_bounds(self):
        if not self._schedule:
            return
        self._min_start_time = self._schedule[0][0]
        self._max_end_time = max(e[1] for e in self._schedule)

    def _is_overlap(self, event1_start, event1_end, event2_start, event2_end):
        return max(event1_start, event2_start) < min(event1_end, event2_end)

    def _get_event_at_index(self, index):
        return self._schedule[index]

    def _check_single_event(self, existing_event, new_start, new_end):
        return self._is_overlap(existing_event[0], existing_event[1], new_start, new_end)

    def _find_potential_conflicts(self, new_start, new_end):
        for i in range(self._num_events):
            if self._check_single_event(self._get_event_at_index(i), new_start, new_end):
                return True
        return False

    def _validate_new_event(self, new_start, new_end):
        return new_start < new_end

    def has_conflict(self, new_event_start, new_event_end):
        if not self._validate_new_event(new_event_start, new_event_end):
            return True
        if new_event_end <= self._min_start_time or new_event_start >= self._max_end_time:
            return False
        return self._find_potential_conflicts(new_event_start, new_event_end)

def has_conflict(schedule, new_event_start, new_event_end):
    _scheduler_instance = EventScheduler(schedule)
    return _scheduler_instance.has_conflict(new_event_start, new_event_end)

