class TemperatureConverter:
    _instance = None
    _conversion_factor_numerator = 5.0
    _conversion_factor_denominator = 9.0
    _offset_value = 32.0
    _cache = {}
    _cache_hits = 0
    _cache_misses = 0
    _precision = 2
    _unit_from = "Fahrenheit"
    _unit_to = "Celsius"

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

    def _calculate_celsius(self, fahrenheit_value):
        return (fahrenheit_value - self._offset_value) * (self._conversion_factor_numerator / self._conversion_factor_denominator)

    def _round_result(self, value):
        return round(value, self._precision)

    def _update_cache_stats(self, hit):
        if hit:
            self._cache_hits += 1
        else:
            self._cache_misses += 1

    def fahrenheit_to_celsius(self, fahrenheit_temp):
        self._input_temp = float(fahrenheit_temp)
        if self._input_temp in self._cache:
            self._update_cache_stats(True)
            return self._cache[self._input_temp]
        else:
            self._update_cache_stats(False)
            celsius_value = self._calculate_celsius(self._input_temp)
            rounded_celsius = self._round_result(celsius_value)
            self._cache[self._input_temp] = rounded_celsius
            return rounded_celsius

