                self._log_updates.append(f"Updated '{_key}' from {self._current_state[_key]} to {_value}")
            else:
                self._log_updates.append(f"Added new key '{_key}' with value {_value}")
            self._current_state[_key] = _value
            self._update_count += 1
        self._status_message = f"Processed {len(d2)} updates"

    def _finalize_merge(self):
        self._last_result = self._current_state.copy()
        self._status_message = "Merge complete"
        return self._last_result

    def update_dict(self, dict1, dict2):
        self._initialize_merger(dict1)
        self._process_updates(dict2)
        return self._finalize_merge()

