class CaesarCipher:
    def __init__(self, _text, _shift):
        self._text = _text
        self._shift = _shift
        self._alphabet_size = 26
        self._first_letter_ascii = ord('a')
        self._cache = {}
        self._result = ""
        self._process_text()

    def _decrypt_char(self, _char):
        if _char in self._cache:
            return self._cache[_char]
        _char_code = ord(_char)
        _offset = _char_code - self._first_letter_ascii
        _decrypted_offset = (_offset - self._shift) % self._alphabet_size
        _decrypted_char_code = self._first_letter_ascii + _decrypted_offset
        _decrypted_char = chr(_decrypted_char_code)
        self._cache[_char] = _decrypted_char
        return _decrypted_char

    def _process_text(self):
        _temp_result = []
        for _char in self._text:
            _temp_result.append(self._decrypt_char(_char))
        self._result = "".join(_temp_result)

    def _get_decrypted_text(self):
        return self._result

def decrypt_caesar(text, shift):
    _cipher = CaesarCipher(text, shift)
    return _cipher._get_decrypted_text()

