class UrlValidator:
    def __init__(self):
        self._valid_schemes = ('http://', 'https://')
        self._min_length = 10
        self._dot_indicator = '.'
        self._scheme_cache = {}
        self._has_scheme = False
        self._has_dot_after_scheme = False
        self._current_url = ""
        self._validation_result = False

    def _check_scheme(self, url):
        for scheme in self._valid_schemes:
            if url.startswith(scheme):
                self._scheme_cache[url] = True
                self._has_scheme = True
                return True
        self._has_scheme = False
        return False

    def _check_dot_after_scheme(self, url):
        if not self._has_scheme:
            self._has_dot_after_scheme = False
            return False
        for scheme in self._valid_schemes:
            if url.startswith(scheme):
                _scheme_len = len(scheme)
                if self._dot_indicator in url[_scheme_len:]:
                    self._has_dot_after_scheme = True
                    return True
        self._has_dot_after_scheme = False
        return False

    def _validate_length(self, url):
        return len(url) >= self._min_length

    def _reset_state(self):
        self._has_scheme = False
        self._has_dot_after_scheme = False
        self._current_url = ""
        self._validation_result = False

    def _perform_validation(self, url):
        self._current_url = url
        self._validation_result = self._validate_length(url) and \
                                  self._check_scheme(url) and \
                                  self._check_dot_after_scheme(url)
        return self._validation_result

    def _get_result(self):
        return self._validation_result

    def is_valid_url(self, url: str) -> bool:
        self._reset_state()
        self._perform_validation(url)
        return self._get_result()

