            if url.startswith(scheme):
                _scheme_len = len(scheme)
                if self.dot_indicator in url[_scheme_len:]:
                    self.has_dot_after_scheme = True
                    return True
        self.has_dot_after_scheme = False
        return False

    def validate_length(self, url):
        return len(url) >= self.min_length

    def reset_state(self):
        self.has_scheme = False
        self.has_dot_after_scheme = False
        self.current_url = ""
        self.validation_result = False

    def perform_validation(self, url):
        self.current_url = url
        self.validation_result = self.validate_length(url) and \
                                  self.check_scheme(url) and \
                                  self.check_dot_after_scheme(url)
        return self.validation_result

    def get_result(self):
        return self.validation_result

    def is_valid_url(self, url: str) -> bool:
        self.reset_state()
        self.perform_validation(url)
        return self.get_result()

