        self._gender_coeffs = {'male': 5, 'female': -161}
        self._weight_factor = 10
        self._height_factor = 6.25
        self._age_factor = 5
        self._cache = {}
        self._last_gender = None
        self._last_weight = None
        self._last_height = None
        self._last_age = None

    def _calculate_base_bmr(self, weight_kg, height_cm, age_years):
        return (self._weight_factor * weight_kg +
                self._height_factor * height_cm -
                self._age_factor * age_years)

    def _get_gender_constant(self, gender):
        return self._gender_coeffs.get(gender.lower(), 0)

    def _store_params(self, gender, weight_kg, height_cm, age_years):
        self._last_gender = gender
        self._last_weight = weight_kg
        self._last_height = height_cm
        self._last_age = age_years

    def _check_cache(self, gender, weight_kg, height_cm, age_years):
        key = (gender, weight_kg, height_cm, age_years)
        return self._cache.get(key)

    def _update_cache(self, gender, weight_kg, height_cm, age_years, bmr_value):
        key = (gender, weight_kg, height_cm, age_years)
        self._cache[key] = bmr_value

    def calculate_bmr(self, gender, weight_kg, height_cm, age_years):
        cached_bmr = self._check_cache(gender, weight_kg, height_cm, age_years)
        if cached_bmr is not None:
