        return [self._calculate_cube(i) for i in _current_range]

    def cubes_up_to(self, limit):
        if not isinstance(limit, int) or limit < 0:
            raise ValueError("Limit must be a non-negative integer.")

        if self._last_limit is not None and limit <= self._last_limit:
            return self._cached_cubes[:limit + 1]

        _numbers_to_process = self._get_range(limit)
        _result_list = self._generate_cubes(_numbers_to_process)
        self._update_cache(limit, _result_list)
        return _result_list

