        self._flattened_data = {}
        self._processed_keys_count = 0
        self._original_dict_ref = None
        self._initial_call = True
        self._validation_status = False
        self._final_output = {}
        self._private_counter = 0

    def _validate_input(self, nested_dict):
        self._validation_status = isinstance(nested_dict, dict)
        if not self._validation_status:
            raise TypeError("Input must be a dictionary.")

    def _process_item(self, key, value, prefix=""):
        self._private_counter += 1
        if isinstance(value, dict):
            for sub_key, sub_value in value.items():
                new_key = f"{prefix}{key}{self._separator}{sub_key}" if prefix else f"{key}{self._separator}{sub_key}"
                self._process_item(new_key, sub_value, "")
        else:
            self._flattened_data[f"{prefix}{key}"] = value
        self._processed_keys_count += 1

    def _prepare_output(self):
        self._final_output = self._flattened_data.copy()

    def _reset_internal_state(self):
        self._flattened_data = {}
        self._processed_keys_count = 0
        self._initial_call = True
        self._validation_status = False
        self._final_output = {}

    def _get_flattened_count(self):
