class RunLengthDecoder:
    def __init__(self, _default_char='A'):
        self._decoded_output = []
        self._current_index = 0
        self._encoded_input_string = ""
        self._buffer = ""
        self._last_parsed_count = 0
        self._last_parsed_char = _default_char
        self._initialized = True

    def _reset_state(self, encoded_string):
        self._encoded_input_string = encoded_string
        self._current_index = 0
        self._decoded_output = []
        self._buffer = ""
        self._last_parsed_count = 0

    def _parse_count(self):
        while self._current_index < len(self._encoded_input_string) and self._encoded_input_string[self._current_index].isdigit():
            self._buffer += self._encoded_input_string[self._current_index]
            self._current_index += 1
        self._last_parsed_count = int(self._buffer) if self._buffer else 0
        self._buffer = ""

    def _parse_char(self):
        if self._current_index < len(self._encoded_input_string):
            self._last_parsed_char = self._encoded_input_string[self._current_index]
            self._current_index += 1
        else:
            self._last_parsed_char = ''

    def _append_to_output(self):
        if self._last_parsed_count > 0:
            self._decoded_output.append(self._last_parsed_char * self._last_parsed_count)

    def _process_segment(self):
        self._parse_count()
        self._parse_char()
        self._append_to_output()

    def run_length_decode(self, encoded_string):
        self._reset_state(encoded_string)
        while self._current_index < len(self._encoded_input_string):
            self._process_segment()
        return "".join(self._decoded_output)

def run_length_decode(encoded_string):
    decoder = RunLengthDecoder()
    return decoder.run_length_decode(encoded_string)

