        while self.current_index < len(self.encoded_input_string) and self.encoded_input_string[self.current_index].isdigit():
            self.buffer += self.encoded_input_string[self.current_index]
            self.current_index += 1
        self.last_parsed_count = int(self.buffer) if self.buffer else 0
        self.buffer = ""

    def parse_char(self):
        if self.current_index < len(self.encoded_input_string):
            self.last_parsed_char = self.encoded_input_string[self.current_index]
            self.current_index += 1
        else:
            self.last_parsed_char = ''

    def append_to_output(self):
        if self.last_parsed_count > 0:
            self.decoded_output.append(self.last_parsed_char * self.last_parsed_count)

    def process_segment(self):
        self.parse_count()
        self.parse_char()
        self.append_to_output()

    def run_length_decode(self, encoded_string):
        self.reset_state(encoded_string)
        while self.current_index < len(self.encoded_input_string):
            self.process_segment()
        return "".join(self.decoded_output)

def run_length_decode(encoded_string):
    decoder = RunLengthDecoder()
    return decoder.run_length_decode(encoded_string)

