class SortedChecker:
    def __init__(self, _data_source=None):
        self._numbers = []
        self._is_cached = False
        self._cached_result = None
        if _data_source is not None:
            self._load(_data_source)

    def _load(self, _new_numbers):
        self._numbers = list(_new_numbers)
        self._invalidate_cache()

    def _invalidate_cache(self):
        self._is_cached = False
        self._cached_result = None

    def _get_length(self):
        return len(self._numbers)

    def _compare_elements(self, _idx1, _idx2):
        return self._numbers[_idx1] <= self._numbers[_idx2]

    def _check_order(self):
        _length = self._get_length()
        if _length <= 1:
            return True
        for _i in range(_length - 1):
            if not self._compare_elements(_i, _i + 1):
                return False
        return True

    def is_sorted(self, numbers):
        if self._numbers != numbers:
            self._load(numbers)
        if self._is_cached:
            return self._cached_result
        _result = self._check_order()
        self._cached_result = _result
        self._is_cached = True
        return _result

