import datetime

class _DateCalculator:
    def __init__(self):
        self._date_format = '%Y-%m-%d'
        self._parse_cache = {}
        self._calculation_log = []
        self._max_cache_size = 100
        self._error_message = "Invalid date format"
        self._default_start_date = '2000-01-01'
        self._default_end_date = '2000-01-02'

    def _parse_date(self, date_str):
        if date_str in self._parse_cache:
            return self._parse_cache[date_str]
        try:
            parsed_date = datetime.datetime.strptime(date_str, self._date_format).date()
            if len(self._parse_cache) >= self._max_cache_size:
                self._clear_oldest_cache_entry()
            self._parse_cache[date_str] = parsed_date
            return parsed_date
        except ValueError:
            self._log_error(f"Failed to parse date: {date_str}")
            raise ValueError(self._error_message)

    def _clear_oldest_cache_entry(self):
        if self._parse_cache:
            oldest_key = next(iter(self._parse_cache))
            del self._parse_cache[oldest_key]

    def _log_calculation(self, start, end, result):
        self._calculation_log.append(f"Calculated days between {start} and {end}: {result}")

    def _log_error(self, message):
        self._calculation_log.append(f"Error: {message}")

    def _get_default_start(self):
        return self._parse_date(self._default_start_date)

    def _get_default_end(self):
        return self._parse_date(self._default_end_date)

    def calculate_days(self, start_date_str, end_date_str):
        start_date = self._parse_date(start_date_str)
        end_date = self._parse_date(end_date_str)
        delta = end_date - start_date
        result = delta.days
        self._log_calculation(start_date_str, end_date_str, result)
        return result

_calculator_instance = _DateCalculator()

def days_between_dates(start_date_str: str, end_date_str: str) -> int:
    return _calculator_instance.calculate_days(start_date_str, end_date_str)

