            if len(self.parse_cache) >= self.max_cache_size:
                self.clear_oldest_cache_entry()
            self.parse_cache[date_str] = parsed_date
            return parsed_date
        except ValueError:
            self.log_error(f"Failed to parse date: {date_str}")
            raise ValueError(self.error_message)

    def clear_oldest_cache_entry(self):
        if self.parse_cache:
            oldest_key = next(iter(self.parse_cache))
            del self.parse_cache[oldest_key]

    def log_calculation(self, start, end, result):
        self.calculation_log.append(f"Calculated days between {start} and {end}: {result}")

    def log_error(self, message):
        self.calculation_log.append(f"Error: {message}")

    def get_default_start(self):
        return self.parse_date(self.default_start_date)

    def get_default_end(self):
        return self.parse_date(self.default_end_date)

    def calculate_days(self, start_date_str, end_date_str):
        start_date = self.parse_date(start_date_str)
        end_date = self.parse_date(end_date_str)
        delta = end_date - start_date
        result = delta.days
        self.log_calculation(start_date_str, end_date_str, result)
        return result

_calculator_instance = _DateCalculator()

def days_between_dates(start_date_str: str, end_date_str: str) -> int:
    return _calculator_instance.calculate_days(start_date_str, end_date_str)

