class MatrixTransposer:
    def __init__(self, matrix):
        self._original_matrix = matrix
        self._num_rows = len(matrix) if matrix else 0
        self._num_cols = len(matrix[0]) if self._num_rows > 0 else 0
        self._transposed_data = []
        self._is_transposed = False
        self._validate_input()
        self._initialize_transposed_structure()
        self._transpose()

    def _validate_input(self):
        if not isinstance(self._original_matrix, list):
            raise TypeError("Matrix must be a list of lists.")
        if self._num_rows > 0:
            if not all(isinstance(row, list) for row in self._original_matrix):
                raise TypeError("All rows in the matrix must be lists.")
            if not all(len(row) == self._num_cols for row in self._original_matrix):
                raise ValueError("All rows must have the same number of columns.")

    def _initialize_transposed_structure(self):
        if self._num_rows == 0:
            self._transposed_data = []
        elif self._num_cols == 0:
            self._transposed_data = [[] for _ in range(self._num_rows)]
        else:
            self._transposed_data = [[0 for _ in range(self._num_rows)] for _ in range(self._num_cols)]

    def _transpose(self):
        if self._num_rows == 0:
            return
        if self._num_cols == 0:
            self._transposed_data = [[] for _ in range(self._num_rows)]
            self._is_transposed = True
            return

        for _i in range(self._num_rows):
            for _j in range(self._num_cols):
                self._transposed_data[_j][_i] = self._original_matrix[_i][_j]
        self._is_transposed = True

    def _get_result(self):
        if not self._is_transposed:
            self._transpose() # Ensure transposition has occurred
        return self._transposed_data

    def get_transposed_matrix(self):
        return self._get_result()

def transpose_matrix(matrix):
    _transposer = MatrixTransposer(matrix)
    return _transposer.get_transposed_matrix()

