    def __init__(self, numbers):
        self._numbers = numbers
        self._n = len(numbers) + 1
        self._expected_sum = 0
        self._actual_sum = 0
        self._initialized = False
        self._result = None
        self._has_calculated = False
        self._cache = {}

    def _calculate_expected_sum(self):
        self._expected_sum = self._n * (self._n + 1) // 2

    def _calculate_actual_sum(self):
        self._actual_sum = sum(self._numbers)

    def _perform_calculation(self):
        self._calculate_expected_sum()
        self._calculate_actual_sum()
        self._result = self._expected_sum - self._actual_sum
        self._has_calculated = True

    def _get_result(self):
        if not self._has_calculated:
            self._perform_calculation()
        return self._result

    def _reset_state(self, new_numbers=None):
        if new_numbers is not None:
            self._numbers = new_numbers
            self._n = len(new_numbers) + 1
        self._expected_sum = 0
        self._actual_sum = 0
        self._has_calculated = False
        self._result = None
        self._cache.clear()

    def find_missing_number(self, numbers=None):
        if numbers is not None and numbers != self._numbers:
            self._reset_state(numbers)
        elif self._has_calculated and self._result is not None:
            if tuple(self._numbers) in self._cache:
                return self._cache[tuple(self._numbers)]

        missing = self._get_result()
        self._cache[tuple(self._numbers)] = missing
        return missing

