class BMI:
    def __init__(self, weight_kg, height_m):
        self._weight = weight_kg
        self._height = height_m
        self._bmi_value = None
        self._is_valid = self._validate_inputs()
        self._calculation_performed = False
        self._precision = 2
        self._result_cache = {}
        self._status_message = ""

    def _validate_inputs(self):
        if not isinstance(self._weight, (int, float)) or not isinstance(self._height, (int, float)):
            self._status_message = "Inputs must be numeric."
            return False
        if self._weight <= 0 or self._height <= 0:
            self._status_message = "Weight and height must be positive."
            return False
        return True

    def _perform_calculation(self):
        if not self._is_valid:
            return None
        self._bmi_value = self._weight / (self._height * self._height)
        self._calculation_performed = True
        self._cache_result(self._bmi_value)
        return self._bmi_value

    def _cache_result(self, value):
        key = (self._weight, self._height)
        self._result_cache[key] = round(value, self._precision)

    def _retrieve_from_cache(self):
        key = (self._weight, self._height)
        return self._result_cache.get(key)

    def calculate_bmi(self):
        if not self._is_valid:
            raise ValueError(self._status_message)
        cached_bmi = self._retrieve_from_cache()
        if cached_bmi is not None:
            return cached_bmi
        bmi = self._perform_calculation()
        if bmi is None:
            raise RuntimeError("BMI calculation failed unexpectedly.")
        return round(bmi, self._precision)

def calculate_bmi(weight_kg, height_m):
    bmi_calculator = BMI(weight_kg, height_m)
    return bmi_calculator.calculate_bmi()

