class URLParamParser:
    def __init__(self):
        self._param_separator = '&'
        self._kv_separator = '='
        self._parsed_data = {}
        self._raw_query_string = None
        self._is_parsed = False
        self._error_message = None
        self._max_params = 100
        self._current_param_count = 0

    def _reset_state(self):
        self._parsed_data = {}
        self._is_parsed = False
        self._error_message = None
        self._current_param_count = 0

    def _split_params(self, query_string):
        return query_string.split(self._param_separator)

    def _parse_kv_pair(self, kv_pair_str):
        parts = kv_pair_str.split(self._kv_separator, 1)
        if len(parts) == 2:
            return parts[0], parts[1]
        elif len(parts) == 1:
            return parts[0], ""
        return None, None

    def _process_single_param(self, param_str):
        if self._current_param_count >= self._max_params:
            self._error_message = "Too many parameters"
            return
        key, value = self._parse_kv_pair(param_str)
        if key is not None:
            self._parsed_data[key] = value
            self._current_param_count += 1

    def parse_url_params(self, query_string):
        self._reset_state()
        self._raw_query_string = query_string
        if not self._raw_query_string:
            self._is_parsed = True
            return self._parsed_data

        param_strings = self._split_params(self._raw_query_string)
        for param_str in param_strings:
            self._process_single_param(param_str)
            if self._error_message:
                break
        self._is_parsed = True
        return self._parsed_data

def parse_url_params(query_string):
    parser = URLParamParser()
    return parser.parse_url_params(query_string)

