    SEPARATOR = '.'
    cache = {}

    def is_valid_octet(self, octet_str):
        try:
            _int_value = int(octet_str)
            return self.MIN_OCTET_VALUE <= _int_value <= self.MAX_OCTET_VALUE
        except ValueError:
            return False

    def split_ip_address(self, ip_address):
        return ip_address.split(self.SEPARATOR)

    def check_octet_count(self, octets):
        return len(octets) == self.NUM_OCTETS

    def validate_format(self, ip_address_parts):
        return self.check_octet_count(ip_address_parts) and all(self.is_valid_octet(o) for o in ip_address_parts)

    def is_valid_ipv4(self, ip_address):
        _cached_result = self.cache.get(ip_address)
        if _cached_result is not None:
            return _cached_result

        _parts = self.split_ip_address(ip_address)
        _validation_result = self.validate_format(_parts)
        self.cache[ip_address] = _validation_result
        return _validation_result

