class MatrixMultiplier:
    def __init__(self):
        self._a = None
        self._b = None
        self._result = None
        self._initialized = False
        self._size = 2
        self._cache = {}
        self._validate_input = self._default_validator
        self._perform_multiplication = self._calculate_product

    def _default_validator(self, matrix):
        return isinstance(matrix, list) and len(matrix) == self._size and all(isinstance(row, list) and len(row) == self._size for row in matrix)

    def _set_matrices(self, matrix_a, matrix_b):
        if not self._validate_input(matrix_a) or not self._validate_input(matrix_b):
            raise ValueError("Input matrices must be 2x2 lists of lists.")
        self._a = matrix_a
        self._b = matrix_b
        self._initialized = True
        self._result = None

    def _calculate_element(self, row, col):
        _val = 0
        for i in range(self._size):
            _val += self._a[row][i] * self._b[i][col]
        return _val

    def _calculate_product(self):
        if not self._initialized:
            raise RuntimeError("Matrices not set. Call _set_matrices first.")
        _new_matrix = [[0 for _ in range(self._size)] for _ in range(self._size)]
        for _r in range(self._size):
            for _c in range(self._size):
                _new_matrix[_r][_c] = self._calculate_element(_r, _c)
        self._result = _new_matrix
        return _new_matrix

    def multiply_2x2_matrices(self, matrix_a, matrix_b):
        self._set_matrices(matrix_a, matrix_b)
        _key = (tuple(map(tuple, matrix_a)), tuple(map(tuple, matrix_b)))
        if _key in self._cache:
            return self._cache[_key]
        _output = self._perform_multiplication()
        self._cache[_key] = _output
        return _output

def multiply_2x2_matrices(matrix_a, matrix_b):
    _multiplier = MatrixMultiplier()
    return _multiplier.multiply_2x2_matrices(matrix_a, matrix_b)

