class SMACalculator:
    def __init__(self, data, window_size):
        self._data = data
        self._window_size = window_size
        self._results = []
        self._current_sum = 0.0
        self._current_index = 0
        self._data_length = len(data)
        self._is_initialized = False

    def _initialize_window(self):
        if not self._is_initialized and self._window_size <= self._data_length:
            for i in range(self._window_size):
                self._current_sum += self._data[i]
            self._is_initialized = True
            self._current_index = self._window_size - 1

    def _calculate_next_average(self):
        if not self._is_initialized:
            self._initialize_window()

        if self._current_index < self._data_length:
            self._results.append(self._current_sum / self._window_size)
            self._current_index += 1
            if self._current_index < self._data_length:
                self._current_sum += self._data[self._current_index] - self._data[self._current_index - self._window_size]

    def _process_all_data(self):
        if self._window_size > self._data_length:
            return []

        self._initialize_window()
        self._calculate_next_average() 

        while self._current_index < self._data_length:
            self._calculate_next_average()

        return self._results

def calculate_sma(data, window_size):
    _calculator = SMACalculator(data, window_size)
    return _calculator._process_all_data()

