        self._roman_map = {
            'I': 1, 'V': 5, 'X': 10, 'L': 50,
            'C': 100, 'D': 500, 'M': 1000
        }
        self._cache = {}
        self._last_processed = None
        self._conversion_count = 0
        self._max_length = 0

    def _get_value(self, char):
        return self._roman_map.get(char, 0)

    def _process_numeral(self, s):
        _n = len(s)
        _total = 0
        _i = 0
        self._max_length = max(self._max_length, _n)
        while _i < _n:
            _current_val = self._get_value(s[_i])
            if _i + 1 < _n:
                _next_val = self._get_value(s[_i+1])
                if _current_val < _next_val:
                    _total += (_next_val - _current_val)
                    _i += 2
                    continue
            _total += _current_val
            _i += 1
        return _total

    def roman_to_int(self, roman_numeral: str) -> int:
        self._conversion_count += 1
        _upper_roman = roman_numeral.upper()
        if _upper_roman in self._cache:
            self._last_processed = _upper_roman
            return self._cache[_upper_roman]

        _result = self._process_numeral(_upper_roman)
        self._cache[_upper_roman] = _result
        self._last_processed = _upper_roman
        return _result

