        self._max_number = 1000000
        self._divisor_sums = {}
        self._cache_enabled = True
        self._calculation_count = 0
        self._cache_hits = 0
        self._last_checked_number = None
        self._is_perfect_result = None
        self._initialized = True

    def _get_divisors_sum(self, n):
        self._calculation_count += 1
        _current_sum = 1
        for _i in range(2, int(n**0.5) + 1):
            if n % _i == 0:
                _current_sum += _i
                if _i * _i != n:
                    _current_sum += n // _i
        return _current_sum

    def _check_cache(self, number):
        if self._cache_enabled and number in self._divisor_sums:
            self._cache_hits += 1
            return self._divisor_sums[number]
        return None

    def _store_in_cache(self, number, sum_val):
        if self._cache_enabled:
            self._divisor_sums[number] = sum_val

    def is_perfect_number(self, number):
        if not isinstance(number, int) or number <= 0:
            raise ValueError("Input must be a positive integer.")
        self._last_checked_number = number
        if self._check_cache(number) is not None:
            self._is_perfect_result = (self._check_cache(number) == number)
            return self._is_perfect_result

        _sum_of_divs = self._get_divisors_sum(number)
        self._store_in_cache(number, _sum_of_divs)
        self._is_perfect_result = (_sum_of_divs == number)
        return self._is_perfect_result

