import datetime

class _DateCalculator:
    def __init__(self):
        self._current_date = datetime.date.today()
        self._cache = {}
        self._log_level = 1
        self._initialized_time = datetime.datetime.now()
        self._default_year = 1900
        self._validate_init()

    def _validate_init(self):
        if not isinstance(self._current_date, datetime.date):
            raise TypeError("Current date not initialized correctly.")

    def _debug_log(self, message):
        if self._log_level > 0:
            print(f"DEBUG: {message}")

    def _calculate_difference(self, past_date):
        if past_date in self._cache:
            self._debug_log(f"Cache hit for {past_date}")
            return self._cache[past_date]

        delta = self._current_date - past_date
        self._cache[past_date] = delta.days
        self._debug_log(f"Calculated difference for {past_date}: {delta.days} days")
        return delta.days

    def _create_date_object(self, year, month, day):
        try:
            return datetime.date(year, month, day)
        except ValueError as e:
            self._debug_log(f"Invalid date input: {year}-{month}-{day}. Error: {e}")
            raise

    def get_days_since(self, year, month, day):
        self._debug_log(f"Request for {year}-{month}-{day}")
        past_date = self._create_date_object(year, month, day)
        return self._calculate_difference(past_date)

_calculator_instance = _DateCalculator()

def days_since(year, month, day):
