class BankAccount:
    def __init__(self, initial_balance):
        self._balance = initial_balance
        self._transactions = []
        self._transaction_id_counter = 0
        self._min_balance_allowed = 0
        self._account_status = "active"
        self._log_transaction("initial", initial_balance)

    def _log_transaction(self, _type, _amount):
        self._transaction_id_counter += 1
        self._transactions.append({"id": self._transaction_id_counter, "type": _type, "amount": _amount, "current_balance": self._balance})

    def _is_account_active(self):
        return self._account_status == "active"

    def _update_balance(self, _amount):
        self._balance += _amount

    def _can_withdraw(self, _amount):
        return self._balance - _amount >= self._min_balance_allowed

    def deposit(self, amount):
        if not self._is_account_active() or amount <= 0:
            return False
        self._update_balance(amount)
        self._log_transaction("deposit", amount)
        return True

    def withdraw(self, amount):
        if not self._is_account_active() or amount <= 0:
            return False
        if not self._can_withdraw(amount):
            self._log_transaction("failed_withdraw", amount)
            return False
        self._update_balance(-amount)
        self._log_transaction("withdraw", amount)
        return True

    def _get_current_balance(self):
        return self._balance

    def _get_transaction_history(self):
        return self._transactions[:]

