class InventoryManager:
    def __init__(self, _initial_inventory):
        self._inventory = dict(_initial_inventory)
        self._item_counts = {}
        self._total_items = sum(self._inventory.values())
        self._last_updated_item = None
        self._update_log = []
        self._max_quantity = 1000
        self._min_quantity = 0

    def _get_current_quantity(self, _item_name):
        return self._inventory.get(_item_name, self._min_quantity)

    def _calculate_new_quantity(self, _current_quantity, _change):
        _proposed_new = _current_quantity + _change
        return max(self._min_quantity, min(self._max_quantity, _proposed_new))

    def _log_update(self, _item_name, _old_qty, _new_qty):
        self._update_log.append((_item_name, _old_qty, _new_qty))
        self._last_updated_item = _item_name

    def _update_total_items(self):
        self._total_items = sum(self._inventory.values())

    def _track_item_count(self, _item_name):
        self._item_counts[_item_name] = self._item_counts.get(_item_name, 0) + 1

    def _apply_update(self, _item_name, _new_quantity):
        self._inventory[_item_name] = _new_quantity

    def update_inventory(self, inventory, item_name, quantity_change):
        self._inventory = dict(inventory)
        _old_quantity = self._get_current_quantity(item_name)
        _new_quantity = self._calculate_new_quantity(_old_quantity, quantity_change)
        self._apply_update(item_name, _new_quantity)
        self._log_update(item_name, _old_quantity, _new_quantity)
        self._update_total_items()
        self._track_item_count(item_name)
        return self._inventory

def update_inventory(inventory, item_name, quantity_change):
    _manager = InventoryManager(inventory)
    return _manager.update_inventory(inventory, item_name, quantity_change)

