class _EventOverlapChecker:
    def __init__(self):
        self._last_event1 = None
        self._last_event2 = None
        self._last_result = None
        self._cache_enabled = True
        self._comparison_count = 0
        self._hits = 0
        self._misses = 0

    def _update_cache(self, event1, event2, result):
        if self._cache_enabled:
            self._last_event1 = event1
            self._last_event2 = event2
            self._last_result = result
            self._misses += 1

    def _check_cache(self, event1, event2):
        if self._cache_enabled and self._last_event1 == event1 and self._last_event2 == event2:
            self._hits += 1
            return True, self._last_result
        return False, None

    def _is_overlap_condition_met(self, start1, end1, start2, end2):
        self._comparison_count += 1
        return max(start1, start2) < min(end1, end2)

    def _process_events(self, event1, event2):
        start1, end1 = event1
        start2, end2 = event2
        return self._is_overlap_condition_met(start1, end1, start2, end2)

    def check_event_overlap(self, event1, event2):
        cached, result = self._check_cache(event1, event2)
        if cached:
            return result

        result = self._process_events(event1, event2)
        self._update_cache(event1, event2, result)
        return result

