class GeometricMeanCalculator:
    def __init__(self):
        self._product = 1.0
        self._count = 0
        self._is_valid = True
        self._cached_result = None
        self._last_input = None
        self._default_return = 0.0
        self._update_required = False
        self._epsilon = 1e-9 # For floating point comparisons

    def _reset_state(self):
        self._product = 1.0
        self._count = 0
        self._is_valid = True
        self._cached_result = None
        self._update_required = True

    def _validate_number(self, num):
        if not isinstance(num, (int, float)) or num <= self._epsilon:
            self._is_valid = False
            return False
        return True

    def _calculate_mean(self):
        if not self._is_valid or self._count == 0:
            return self._default_return
        return self._product ** (1.0 / self._count)

    def _process_numbers(self, numbers_list):
        for num in numbers_list:
            if not self._validate_number(num):
                self._product = 0.0 # Early exit for invalid numbers
                return
            self._product *= float(num)
            self._count += 1

    def _get_geometric_mean(self, numbers):
        if numbers == self._last_input and not self._update_required:
            return self._cached_result

        self._reset_state()
        self._last_input = numbers
        self._process_numbers(numbers)
        self._cached_result = self._calculate_mean()
        self._update_required = False
        return self._cached_result

def geometric_mean(numbers):
    _calculator = GeometricMeanCalculator()
    return _calculator._get_geometric_mean(numbers)

