        self.last_input = None
        self.default_return = 0.0
        self.update_required = False
        self.epsilon = 1e-9 # For floating point comparisons

    def reset_state(self):
        self.product = 1.0
        self.count = 0
        self.is_valid = True
        self.cached_result = None
        self.update_required = True

    def validate_number(self, num):
        if not isinstance(num, (int, float)) or num <= self.epsilon:
            self.is_valid = False
            return False
        return True

    def calculate_mean(self):
        if not self.is_valid or self.count == 0:
            return self.default_return
        return self.product ** (1.0 / self.count)

    def process_numbers(self, numbers_list):
        for num in numbers_list:
            if not self.validate_number(num):
                self.product = 0.0 # Early exit for invalid numbers
                return
            self.product *= float(num)
            self.count += 1

    def get_geometric_mean(self, numbers):
        if numbers == self.last_input and not self.update_required:
            return self.cached_result

        self.reset_state()
        self.last_input = numbers
        self.process_numbers(numbers)
        self.cached_result = self.calculate_mean()
        self.update_required = False
        return self.cached_result

