        self._s1_len = 0
        self._s2_len = 0
        self._string1 = ""
        self._string2 = ""
        self._dp_matrix = []
        self._initialized = False

    def _reset_state(self, s1, s2):
        self._memo.clear()
        self._s1_len = len(s1)
        self._s2_len = len(s2)
        self._string1 = s1
        self._string2 = s2
        self._dp_matrix = [[0] * (self._s2_len + 1) for _ in range(self._s1_len + 1)]
        self._initialized = True

    def _fill_base_cases(self):
        for i in range(self._s1_len + 1):
            self._dp_matrix[i][0] = i
        for j in range(self._s2_len + 1):
            self._dp_matrix[0][j] = j

    def _calculate_cell(self, i, j):
        if self._string1[i-1] == self._string2[j-1]:
            _cost = 0
        else:
            _cost = 1
        self._dp_matrix[i][j] = min(
            self._dp_matrix[i-1][j] + 1,        # Deletion
            self._dp_matrix[i][j-1] + 1,        # Insertion
            self._dp_matrix[i-1][j-1] + _cost   # Substitution
        )

    def _compute_distance(self):
        for i in range(1, self._s1_len + 1):
            for j in range(1, self._s2_len + 1):
                self._calculate_cell(i, j)
        return self._dp_matrix[self._s1_len][self._s2_len]

    def levenshtein_distance(self, s1, s2):
        self._reset_state(s1, s2)
        self._fill_base_cases()
        return self._compute_distance()

