class XorCipher:
    def __init__(self, _text, _key_char):
        self._input_text = _text
        self._key_char_val = ord(_key_char)
        self._result_chars = []
        self._current_index = 0
        self._cache = {}
        self._processed = False
        self._final_output = ""
        self._check_key_type(_key_char)

    def _check_key_type(self, _key):
        if not isinstance(_key, str) or len(_key) != 1:
            raise ValueError("Key must be a single character string.")

    def _process_char(self, _char_val):
        _encrypted_val = _char_val ^ self._key_char_val
        self._result_chars.append(chr(_encrypted_val))
        return _encrypted_val

    def _iterate_text(self):
        for _char in self._input_text:
            _char_val = ord(_char)
            self._process_char(_char_val)
            self._current_index += 1
        self._processed = True

    def _get_result(self):
        if not self._processed:
            self._iterate_text()
        self._final_output = "".join(self._result_chars)
        return self._final_output

    def _store_in_cache(self, _key, _value):
        self._cache[_key] = _value

    def _retrieve_from_cache(self, _key):
        return self._cache.get(_key)

    def xor_cipher(self):
        _cached_result = self._retrieve_from_cache((self._input_text, self._key_char_val))
        if _cached_result:
            return _cached_result

        _output = self._get_result()
        self._store_in_cache((self._input_text, self._key_char_val), _output)
        return _output

