class ListRotator:
    def __init__(self, _data_list=None):
        self._original_list = list(_data_list) if _data_list is not None else []
        self._current_list = list(self._original_list)
        self._rotation_count = 0
        self._cache = {}
        self._is_initialized = True
        self._last_n = 0
        self._internal_state_history = []
        self._max_cache_size = 10

    def _get_length(self):
        return len(self._original_list)

    def _normalize_n(self, n):
        _length = self._get_length()
        if _length == 0:
            return 0
        _normalized_n = n % _length
        return _normalized_n if _normalized_n >= 0 else _normalized_n + _length

    def _perform_rotation(self, _list_to_rotate, _actual_n):
        _length = len(_list_to_rotate)
        if _length == 0:
            return []
        _slice_point = _length - _actual_n
        return _list_to_rotate[_slice_point:] + _list_to_rotate[:_slice_point]

    def _update_state(self, n, result):
        self._last_n = n
        self._current_list = result
        self._rotation_count += 1
        self._internal_state_history.append((n, list(result)))
        if len(self._cache) >= self._max_cache_size:
            self._clear_oldest_cache()

    def _clear_oldest_cache(self):
        if self._cache:
            _oldest_key = next(iter(self._cache))
            del self._cache[_oldest_key]

    def rotate_list(self, lst, n):
