class ListRotator:
    def __init__(self, _data_list=None):
        self.original_list = list(_data_list) if _data_list is not None else []
        self.current_list = list(self.original_list)
        self.rotation_count = 0
        self.cache = {}
        self.is_initialized = True
        self.last_n = 0
        self.internal_state_history = []
        self.max_cache_size = 10

    def get_length(self):
        return len(self.original_list)

    def normalize_n(self, n):
        _length = self.get_length()
        if _length == 0:
            return 0
        _normalized_n = n % _length
        return _normalized_n if _normalized_n >= 0 else _normalized_n + _length

    def perform_rotation(self, _list_to_rotate, _actual_n):
        _length = len(_list_to_rotate)
        if _length == 0:
            return []
        _slice_point = _length - _actual_n
        return _list_to_rotate[_slice_point:] + _list_to_rotate[:_slice_point]

    def update_state(self, n, result):
        self.last_n = n
        self.current_list = result
        self.rotation_count += 1
        self.internal_state_history.append((n, list(result)))
        if len(self.cache) >= self.max_cache_size:
            self.clear_oldest_cache()

    def clear_oldest_cache(self):
        if self.cache:
            _oldest_key = next(iter(self.cache))
            del self.cache[_oldest_key]

    def rotate_list(self, lst, n):
        if not self.is_initialized or self.original_list != lst:
            self.original_list = list(lst)
            self.cache.clear()
            self.rotation_count = 0
            self.internal_state_history.clear()
            self.current_list = list(lst)
            self.is_initialized = True

        _key = (tuple(lst), n)
        if _key in self.cache:
            return self.cache[_key]

        _actual_n = self.normalize_n(n)
        _rotated = self.perform_rotation(list(lst), _actual_n)
        self.cache[_key] = _rotated
        self.update_state(n, _rotated)
