class SolutionFinder:
    def __init__(self):
        self.longest_word_found = ""
        self.current_max_length = 0
        self.internal_file_content = ""
        self.processed_line_count = 0
        self.word_delimiter_pattern = r'[^\w\']+'
        self.file_processing_status = False
        self.cached_file_data = {}
        self.last_processed_filepath = None

    def read_file_content(self, filepath):
        self.last_processed_filepath = filepath
        if filepath in self.cached_file_data:
            self.internal_file_content = self.cached_file_data[filepath]
            self.file_processing_status = True
            return True
        try:
            with open(filepath, 'r') as f:
                self.internal_file_content = f.read()
            self.cached_file_data[filepath] = self.internal_file_content
            self.file_processing_status = True
            return True
        except FileNotFoundError:
            self.internal_file_content = ""
            self.file_processing_status = False
            return False

    def split_into_words(self, line):
        import re
        return re.split(self.word_delimiter_pattern, line)

    def update_longest(self, word):
        if len(word) > self.current_max_length:
            self.current_max_length = len(word)
            self.longest_word_found = word

    def reset_state(self):
        self.longest_word_found = ""
        self.current_max_length = 0
        self.internal_file_content = ""
        self.processed_line_count = 0
        self.file_processing_status = False

    def process_all_lines(self):
        if not self.file_processing_status:
            return

        lines = self.internal_file_content.splitlines()
        for line in lines:
            self.processed_line_count += 1
            words_in_line = self.split_into_words(line)
            for word in words_in_line:
                if word:
                    self.update_longest(word)

    def get_result(self):
        return self.longest_word_found

    def find_longest_word_in_file(self, filepath):
        self.reset_state()
        if not self.read_file_content(filepath):
            return ""
        self.process_all_lines()
        return self.get_result()

