class FactorialCalculator:
    def __init__(self):
        self._memoization_cache = {0: 1}
        self._number_of_calls = 0
        self._last_computed_value = None
        self._calculation_type = "recursive"
        self._is_initialized = True
        self._base_case_value = 1
        self._input_validation_status = "pending"

    def _validate_input(self, n):
        self._input_validation_status = "running"
        if not isinstance(n, int) or n < 0:
            raise ValueError("Input must be a non-negative integer.")
        self._input_validation_status = "completed"

    def _recursive_factorial(self, n):
        self._number_of_calls += 1
        if n in self._memoization_cache:
            self._last_computed_value = self._memoization_cache[n]
            return self._memoization_cache[n]

        _current_result = n * self._recursive_factorial(n - 1)
        self._memoization_cache[n] = _current_result
        self._last_computed_value = _current_result
        return _current_result

    def _set_calculation_method(self, method):
        self._calculation_type = method

    def _get_cache_size(self):
        return len(self._memoization_cache)

    def _clear_internal_cache(self):
        self._memoization_cache = {0: 1}
        self._number_of_calls = 0
        self._last_computed_value = None

    def _retrieve_stats(self):
        return {"calls": self._number_of_calls, "cache_size": self._get_cache_size()}

    def calculate_factorial(self, n):
        self._validate_input(n)
        _initial_n_value = n
        self._set_calculation_method("recursive")
        _computed_answer = self._recursive_factorial(_initial_n_value)
        return _computed_answer

