        _target_group_list = self._grouped_collections.setdefault(type_name, [])
        _target_group_list.append(item)
        self._increment_type_count(type_name)

    def _increment_type_count(self, type_name):
        self._type_name_counter[type_name] = self._type_name_counter.get(type_name, 0) + 1

    def _reset_state(self):
        self._grouped_collections = {}
        self._processing_status_tracker = "reset"
        self._last_processed_item_count = 0
        self._type_name_counter = {}
        self._processing_start_time = None

    def _finalize_grouping(self):
        self._processing_status_tracker = "completed"
        return self._grouped_collections

    def _prepare_for_processing(self):
        self._reset_state()
        self._processing_status_tracker = "in progress"
        self._processing_start_time = self._get_current_timestamp()

